
const express = require("express");
const Database = require("better-sqlite3");
const path = require("path");

const app = express();
const db = new Database("students.db");

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

// Create student table
db.exec(`
    CREATE TABLE IF NOT EXISTS students (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        email TEXT NOT NULL,
        phone TEXT,
        department TEXT,
        year TEXT,
        gender TEXT
    )
`);

// Get all students
app.get("/api/students", (req, res) => {
    const students = db.prepare(
        "SELECT * FROM students ORDER BY id DESC"
    ).all();

    res.json(students);
});

// Add student
app.post("/api/students", (req, res) => {
    const { name, email, phone, department, year, gender } = req.body;

    if (!name || !email) {
        return res.status(400).json({
            message: "Name and email are required"
        });
    }

    const result = db.prepare(`
        INSERT INTO students
        (name, email, phone, department, year, gender)
        VALUES (?, ?, ?, ?, ?, ?)
    `).run(name, email, phone, department, year, gender);

    res.status(201).json({
        message: "Student added successfully",
        id: result.lastInsertRowid
    });
});

// Update student
app.put("/api/students/:id", (req, res) => {
    const { name, email, phone, department, year, gender } = req.body;

    if (!name || !email) {
        return res.status(400).json({
            message: "Name and email are required"
        });
    }

    const result = db.prepare(`
        UPDATE students
        SET name=?, email=?, phone=?, department=?, year=?, gender=?
        WHERE id=?
    `).run(name, email, phone, department, year, gender, req.params.id);

    if (result.changes === 0) {
        return res.status(404).json({ message: "Student not found" });
    }

    res.json({ message: "Student updated successfully" });
});

// Delete student
app.delete("/api/students/:id", (req, res) => {
    const result = db.prepare(
        "DELETE FROM students WHERE id=?"
    ).run(req.params.id);

    if (result.changes === 0) {
        return res.status(404).json({ message: "Student not found" });
    }

    res.json({ message: "Student deleted successfully" });
});

// Start server
const PORT = 3000;

app.listen(PORT, () => {
    console.log(`Server running at http://localhost:${PORT}`);
});
